import{_ as o,l as s,o as e,c as i,v as r,p as l,x as t,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Cerf–Kahn 互联","description":"","frontmatter":{"title":"Cerf–Kahn 互联","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cerf-kahn-tcp.md","filePath":"cs/cerf-kahn-tcp.md","lastUpdated":1789023840000}'),p={name:"cs/cerf-kahn-tcp.md"};function f(E,a,T,m,P,C){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="cerf–kahn-互联" tabindex="-1">Cerf–Kahn 互联 <a class="header-anchor" href="#cerf–kahn-互联" aria-label="Permalink to &quot;Cerf–Kahn 互联&quot;">​</a></h1><div class="epigraph"><p>把各异的分组网用网关连起来，端到端提供进程间可靠字节流；网络只转发分组，不要求所有网同一。 </p><footer>—— Cerf and Kahn, A Protocol for Packet Network Intercommunication, IEEE Trans. Comm. 1974</footer></div><p><a href="/cs/lampson-protection">上一课</a>附录对照了逻辑时间。附录对照，不插入主干。主干已在<a href="/cs/layering-e2e">分层与端到端</a>、<a href="/cs/tcp-handshake">TCP 三次握手</a>、<a href="/cs/tcp-seq-rexmit">序号与重传</a>里用过互联与可靠流；这里对照 <strong>1974 原文的问题</strong>：ARPANET 与其他分组网如何互联，进程如何在网关上看到统一的可靠通信。不重做拥塞控制后来的加法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干分层课取端到端原则；TCP 课取三次握手与窗口。1974 文的缺口是互联本身：不同 MTU、不同路由、网关做封装，主机上的协议给出可靠、有序的进程到进程通信。当时 TCP 与 IP 尚未拆成后来的两层，但「网关转发、主机保证」已经在。主干<a href="/cs/ip-subnet">IP 编址</a>是后来的地址语言。</p><p><span class="marginnote">1974 年的 TCP 包含后来 IP 的部分职能。对照时不要把 RFC 791/793 的年份写回这篇论文。拥塞控制是 1980 年代后的主干课，不是 1974 年的章节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进程用端口一类的寻址；分组经网关进入另一网络。可靠性：序号、重传、窗口——主干序号课已展开。附录只对照原文把「互联」与「端到端可靠」写成同一份协议设想，以及为何不要求子网内部可靠。</p>',8)),(e(),l(d,null,{default:t(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NETS%5B%22%E5%90%84%E5%BC%82%E5%88%86%E7%BB%84%E7%BD%91%22%5D%20--%3E%20GW%5B%22%E7%BD%91%E5%85%B3%22%5D%0A%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20REL%5B%22%E5%8F%AF%E9%9D%A0%E8%BF%9B%E7%A8%8B%E6%B5%81%22%5D%0A%20%20GW%20--%3E%20HOST%0A%20%20REL%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%88%86%E5%B1%82%20%2F%20TCP%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>端到端把纠错与排序放在主机，子网可以只尽最大努力。这与 Shannon 信道编码不是一层：一个是比特噪声，一个是分组丢失与乱序。主干<a href="/cs/udp">UDP</a>后来把不可靠暴露给应用，是同一架构上的选项。Cerf–Kahn 不处理 TLS，不处理 BGP 政策——那些是后课与主干后段。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干按层上课：帧、IP、路由、传输。把 1974 插在 DMA 之后当第一课网络，会跳过帧与 MAC。附录只对照互联思想的出处，以及 TCP 课已经取走的可靠流骨架。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把这篇写成「谁发明互联网」的法庭文件。下一篇对照 Codd 1970 如何把数据从文件布局里抽出来，那是数据库第一课的文献。</p><p>网关不是应用层代理：它改的是分组网之间的封装，不是 HTTP。主干防火墙与 TLS 终止是另一层盒子。</p><p>对照结束应回到主干<a href="/cs/layering-e2e">分层与端到端</a>与 TCP 课。1974 文不插入帧与 MAC 之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Cerf and Kahn 1974：网关互联 + 端到端可靠进程通信。</li><li>主干分层与 TCP 课已取用；IP/TCP 拆分与拥塞是后来。</li><li>不插入 MAC 课之前。</li><li>出处：Cerf and Kahn, <em>IEEE Trans. Comm.</em> 22(5), 1974。</li></ul>',10))])}const u=o(p,[["render",f]]);export{B as __pageData,u as default};
